package com.codeguardian.service; import com.codeguardian.entity.SystemConfig; import com.codeguardian.repository.SystemConfigRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*; @Service @RequiredArgsConstructor public class SystemConfigService{private final SystemConfigRepository repo;public Map<String,String> all(){Map<String,String> out=new TreeMap<>();repo.findAll().forEach(c->out.put(c.getKey(),c.getValue()));return out;}public Map<String,String> save(Map<String,String> values){values.forEach((k,v)->repo.save(SystemConfig.builder().key(k).value(v).build()));return all();}public String get(String k,String fallback){return repo.findById(k).map(SystemConfig::getValue).orElse(fallback);}}
